function vocabularyEntries(){
 const reading=study.words.filter(key=>typeof key==='string'&&!key.startsWith('bank:')).map(key=>{const[id,index]=key.split(':');const u=unit(id),p=u?.phrases[Number(index)];return p?{id:key,type:'phrase',category:'reading',en:p[0],meaning:p[1],example:p[2],translation:'',note:'',readingId:id,readingTitle:u.title}:null}).filter(Boolean);
 const categories=['foundation','actions','people','home','world','description','daily','communication','travel','learning','work','software','documents'];
 return [...vocabularyBank].sort((a,b)=>(a.tier==='core'?0:1)-(b.tier==='core'?0:1)||categories.indexOf(a.category)-categories.indexOf(b.category)).concat(reading);
}
const wordPartLabels={n:'名词',v:'动词',adj:'形容词',adv:'副词',pron:'代词',det:'限定词',prep:'介词',conj:'连词',art:'冠词',modal:'情态动词',interj:'感叹词',num:'数词',number:'数词','infinitive marker':'不定式标记'};
function vocabularyParts(entry){
 if(entry.type!=='word')return {meaning:entry.meaning,parts:[{code:'phrase',label:/[…AB]/.test(entry.en)?'句型':'常用表达'}]};
 const match=entry.meaning.match(/^([A-Za-z][A-Za-z./ -]*\.)\s*(.*)$/);let meaning=match?match[2]:entry.meaning;
 const codes=match?match[1].split('/').map(s=>s.replace(/\./g,'').trim()):[];
 for(const m of meaning.matchAll(/\b(n|v|adj|adv|pron|det|prep|conj|art|modal|interj|num|number)\./g))codes.push(m[1]);
 meaning=meaning.replace(/\b(n|v|adj|adv|pron|det|prep|conj|art|modal|interj|num|number)\.\s*/g,'');
 return {meaning,parts:[...new Set(codes)].map(code=>({code,label:wordPartLabels[code]||code}))};
}
function vocabularySentence(entry){return `<details class="vocab-own-sentence"><summary>自己造句</summary><textarea data-vocab-sentence="${esc(entry.id)}" rows="3" lang="en" spellcheck="true" aria-label="用 ${esc(entry.en)} 造句" placeholder="用这个词写一句英语…">${esc(draft('vocabulary:'+entry.id).sentence||'')}</textarea><span role="status">本地保存</span></details>`}
function bindVocabularySentences(root){root.querySelectorAll('[data-vocab-sentence]').forEach(el=>el.oninput=()=>{draft('vocabulary:'+el.dataset.vocabSentence).sentence=el.value;el.nextElementSibling.textContent=saveStudy()?'✓ 已保存':'保存失败，请复制草稿'})}
function vocabularyReview(entry,original='标记为不会'){
 const key=Object.keys(study.mistakes).find(key=>vocabularyReviewMatches(key,study.mistakes[key],entry.id))||'vocabulary:'+entry.id;
 if(study.mistakes[key]){study.mistakes[key].reviewed=false;study.mistakes[key].date=Date.now()}else study.mistakes[key]={kind:'vocabulary',id:entry.readingId||entry.id,entryId:entry.id,title:entry.meaning,original,correction:entry.en,note:[entry.example,entry.translation,entry.note].filter(Boolean).join('\n'),reviewed:false,date:Date.now()};
 study.knownWords=study.knownWords.filter(id=>id!==entry.id);saveStudy();
}
function vocabularyReviewLink(m){return m.entryId?.startsWith('bank:')?'#vocabulary/'+encodeURIComponent(m.entryId):'#read/'+encodeURIComponent(m.id)}
function vocabularyReviewMatches(key,m,id){return m.kind==='vocabulary'&&(m.entryId===id||key==='word:'+id)}
function relatedVocabulary(entry){
 const contains=(text,word)=>new RegExp('\\b'+word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i').test(text);
 return vocabularyBank.filter(x=>entry.type==='word'?x.type==='phrase'&&contains(x.en,entry.en):x.type==='word'&&contains(entry.en,x.en)).slice(0,4);
}
function vocabularyDetails(entry){const related=relatedVocabulary(entry);return `<details class="vocab-detail"><summary>用法与搭配</summary>${entry.note?`<p class="vocab-note">${esc(entry.note)}</p>`:''}${entry.readingId?`<a href="#read/${entry.readingId}">来自：${esc(entry.readingTitle)} →</a>`:''}${related.length?`<div class="vocab-related">${related.map(x=>`<a href="#vocabulary/${encodeURIComponent(x.id)}">${esc(x.en)} →</a>`).join('')}</div>`:''}${vocabularySentence(entry)}</details>`}
function renderVocabulary(routeId){
 const all=vocabularyEntries();let target=null;try{target=all.find(x=>x.id===decodeURIComponent(routeId||''))}catch{}
 let exactId=target?.id||null,tab=routeId==='saved'||target?.readingId?'saved':'bank',status=target&&study.knownWords.includes(target.id)?'all':'unknown',page=0,lastChange=null;
 const pageSize=20;$('#breadcrumb').textContent='词汇与搭配';
 $('#main').innerHTML=`<div class="study-shell vocabulary-shell">${studyHeader('词汇与搭配')}<div class="vocab-controls"><label class="vocab-search"><span class="sr-only">查找词汇</span><input id="vocab-search" type="search" placeholder="查单词、搭配或中文"></label><label class="vocab-scene"><span class="sr-only">场景</span><select id="vocab-category" aria-label="场景"><option value="all">全部场景</option>${Object.entries(vocabularyCategories).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}<option value="reading" id="reading-scene">阅读收藏</option></select></label><button id="vocab-favourites" class="vocab-favourites" aria-pressed="${tab==='saved'}">${tab==='saved'?'★':'☆'} 我的收藏</button></div><div class="vocab-list-heading"><div class="vocab-status-tabs" role="group" aria-label="会不会"><button data-word-status="unknown">不会 <span></span></button><button data-word-status="known">会 <span></span></button><button data-word-status="all">全部 <span></span></button></div><span id="vocab-count" role="status"></span></div><div id="vocab-feedback" class="vocab-feedback" role="status"></div><div id="vocab-content"></div><div id="vocab-pagination" class="vocab-pagination"></div></div>`;
 if(target)$('#vocab-search').value=target.en;
 function matching(){const query=$('#vocab-search').value.trim().toLowerCase();return all.filter(e=>(!exactId||e.id===exactId)&&(tab==='bank'?!e.readingId:study.words.includes(e.id))&&($('#vocab-category').value==='all'||e.category===$('#vocab-category').value)&&[e.en,e.meaning,e.example,e.translation,e.note].join(' ').toLowerCase().includes(query))}
 function feedback(){const root=$('#vocab-feedback');if(!lastChange){root.innerHTML='';return}root.innerHTML=`<span>已标记${lastChange.known?'会':'不会'}：<strong lang="en">${esc(lastChange.entry.en)}</strong></span><button id="undo-vocabulary">撤销</button>`;$('#undo-vocabulary').onclick=()=>{const change=lastChange;study.knownWords=study.knownWords.filter(id=>id!==change.entry.id);if(change.beforeKnown)study.knownWords.push(change.entry.id);for(const[key,m]of Object.entries(study.mistakes))if(vocabularyReviewMatches(key,m,change.entry.id))delete study.mistakes[key];Object.assign(study.mistakes,change.beforeReviews);lastChange=null;saveStudy();draw()}}
 function draw(){
  const matchingItems=matching(),items=matchingItems.filter(e=>status==='all'||(status==='known'?study.knownWords.includes(e.id):!study.knownWords.includes(e.id))),pages=Math.ceil(items.length/pageSize);page=Math.min(page,Math.max(0,pages-1));
  $('#vocab-count').textContent=`${items.length} 条`;$('#reading-scene').hidden=tab!=='saved';
  $('#vocab-favourites').textContent=(tab==='saved'?'★':'☆')+' 我的收藏';$('#vocab-favourites').setAttribute('aria-pressed',String(tab==='saved'));
  document.querySelectorAll('[data-word-status]').forEach(b=>{const active=b.dataset.wordStatus===status;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));b.querySelector('span').textContent=matchingItems.filter(e=>b.dataset.wordStatus==='all'||(b.dataset.wordStatus==='known'?study.knownWords.includes(e.id):!study.knownWords.includes(e.id))).length});feedback();
  if(!items.length){$('#vocab-content').innerHTML=`<div class="empty-state"><p>${tab==='saved'&&!study.words.length?'还没有收藏，点击词卡上的 ☆ 添加。':status==='unknown'?'当前没有不会的词。':'没有匹配的词。'}</p><button id="show-all-words" class="button">${status==='all'?'清除筛选':'查看全部'}</button></div>`;$('#show-all-words').onclick=()=>{if(status==='all'){exactId=null;$('#vocab-search').value='';$('#vocab-category').value='all'}status='all';page=0;draw()};$('#vocab-pagination').innerHTML='';return}
  $('#vocab-content').innerHTML=`<div class="word-table">${items.slice(page*pageSize,(page+1)*pageSize).map(e=>{const parsed=vocabularyParts(e),known=study.knownWords.includes(e.id);return `<article class="word-row ${known?'is-known':''}" data-entry="${esc(e.id)}"><div class="word-row-head"><h2 lang="en">${esc(e.en)}</h2><button class="word-save" data-save-word aria-label="${study.words.includes(e.id)?'取消收藏':'收藏'} ${esc(e.en)}" aria-pressed="${study.words.includes(e.id)}" title="${study.words.includes(e.id)?'取消收藏':'收藏'}">${study.words.includes(e.id)?'★':'☆'}</button></div><div class="word-parts">${parsed.parts.map(p=>`<span class="part-of-speech pos-${esc(p.code.replace(/[^a-z]/g,''))}">${esc(p.label)}${wordPartLabels[p.code]&&p.code!=='infinitive marker'?` <small>${p.code==='number'?'num':esc(p.code)}.</small>`:''}</span>`).join('')}</div><p class="word-meaning">${esc(parsed.meaning)}</p><div class="word-example"><p lang="en">${esc(e.example)}</p>${e.translation?`<p class="word-translation">${esc(e.translation)}</p>`:''}</div>${vocabularyDetails(e)}<div class="word-knowledge" role="group" aria-label="${esc(e.en)} 的掌握情况"><button data-know="false" aria-pressed="${!known}">不会</button><button data-know="true" aria-pressed="${known}">会 <span aria-hidden="true">✓</span></button></div></article>`}).join('')}</div>`;
  document.querySelectorAll('[data-entry]').forEach(row=>{const entry=items.find(x=>x.id===row.dataset.entry);row.querySelector('[data-save-word]').onclick=()=>{const saved=study.words.includes(entry.id);study.words=saved?study.words.filter(id=>id!==entry.id):[...study.words,entry.id];saveStudy();draw()};row.querySelectorAll('[data-know]').forEach(b=>b.onclick=()=>{const known=b.dataset.know==='true',beforeKnown=study.knownWords.includes(entry.id);if(known===beforeKnown)return;const beforeReviews=Object.fromEntries(Object.entries(study.mistakes).filter(([key,m])=>vocabularyReviewMatches(key,m,entry.id)).map(([k,m])=>[k,{...m}]));lastChange={entry,known,beforeKnown,beforeReviews};if(known){study.knownWords.push(entry.id);for(const[key,m]of Object.entries(study.mistakes))if(vocabularyReviewMatches(key,m,entry.id))m.reviewed=true;saveStudy()}else vocabularyReview(entry);const y=window.scrollY;draw();window.scrollTo({top:y,behavior:'instant'})})});bindVocabularySentences($('#vocab-content'));
  $('#vocab-pagination').innerHTML=pages>1?`<button id="vocab-prev" ${page===0?'disabled':''}>← 上一页</button><span>${page+1} / ${pages}</span><button id="vocab-next" ${page===pages-1?'disabled':''}>下一页 →</button>`:'';
  const previous=$('#vocab-prev'),next=$('#vocab-next');if(previous)previous.onclick=()=>{page--;draw();$('#vocab-content').scrollIntoView({behavior:'instant',block:'start'})};if(next)next.onclick=()=>{page++;draw();$('#vocab-content').scrollIntoView({behavior:'instant',block:'start'})};
 }
 $('#vocab-search').oninput=()=>{exactId=null;page=0;draw()};$('#vocab-category').onchange=()=>{exactId=null;page=0;draw()};
 $('#vocab-favourites').onclick=()=>{tab=tab==='saved'?'bank':'saved';exactId=null;page=0;if(tab==='bank'&&$('#vocab-category').value==='reading')$('#vocab-category').value='all';draw()};
 document.querySelectorAll('[data-word-status]').forEach(b=>b.onclick=()=>{status=b.dataset.wordStatus;page=0;draw()});draw();
}
